// SmartTranslateShared.js
//
// Shared config, storage, DeepL, Keychain, and TTS for SmartTranslate v1.
// Imported by SmartTranslate.js and SmartTranslateConversation.js.
//
// Version: 1.0.0

const APP_DIRECTORY = "SmartTranslate";
const CONFIG_FILE = "config.json";
const PEOPLE_FILE = "people.json";
const ACTIVE_SESSION_FILE = "active_session.json";
const CONVERSATIONS_DIRECTORY = "conversations";

const DEEPL_KEYCHAIN_KEY = "SMART_TRANSLATE_DEEPL_API_KEY";
const ELEVENLABS_KEYCHAIN_KEY = "SMART_TRANSLATE_ELEVENLABS_API_KEY";

const DEEPL_TIMEOUT = 15;
const ELEVENLABS_TIMEOUT = 30;

const MAX_INPUT_LENGTH = 5000;
const MAX_VOICE_RESULTS = 50;

const DEFAULT_CONFIG = {
  version: 1,
  languages: {
    primary: "EN-US",
    conversation: "ES",
    defaultTarget: "EN-US"
  },
  input: {
    dictationLanguage: "auto"
  },
  speech: {
    engine: "apple",
    apple: {
      rate: 0.45,
      pitch: 1.0
    },
    elevenlabs: {
      enabled: false,
      modelId: "eleven_multilingual_v2",
      voices: {}
    }
  }
};

const LANGUAGE_OPTIONS = [
  { code: "AR", name: "Arabic" },
  { code: "ZH", name: "Chinese (Simplified)" },
  { code: "NL", name: "Dutch" },
  { code: "EN-US", name: "English (US)" },
  { code: "EN-GB", name: "English (UK)" },
  { code: "FR", name: "French" },
  { code: "DE", name: "German" },
  { code: "HE", name: "Hebrew" },
  { code: "IT", name: "Italian" },
  { code: "JA", name: "Japanese" },
  { code: "KO", name: "Korean" },
  { code: "PL", name: "Polish" },
  { code: "PT-PT", name: "Portuguese" },
  { code: "PT-BR", name: "Portuguese (Brazil)" },
  { code: "RU", name: "Russian" },
  { code: "ES", name: "Spanish" },
  { code: "TR", name: "Turkish" },
  { code: "UK", name: "Ukrainian" }
];

// ============================================================
// iCLOUD STORAGE
// ============================================================

function getFileManager() {
  return FileManager.iCloud();
}

function getAppDirectory() {
  const fm = getFileManager();
  const directory = fm.joinPath(fm.documentsDirectory(), APP_DIRECTORY);
  if (!fm.fileExists(directory)) {
    fm.createDirectory(directory, true);
  }
  return directory;
}

function getConversationsDirectory() {
  const fm = getFileManager();
  const directory = fm.joinPath(getAppDirectory(), CONVERSATIONS_DIRECTORY);
  if (!fm.fileExists(directory)) {
    fm.createDirectory(directory, true);
  }
  return directory;
}

function resolveAppPath(filenameOrPath) {
  if (filenameOrPath.startsWith("/")) {
    return filenameOrPath;
  }
  return getFileManager().joinPath(getAppDirectory(), filenameOrPath);
}

async function ensureDownloaded(path) {
  const fm = getFileManager();
  if (!fm.fileExists(path)) {
    return false;
  }
  if (fm.isFileStoredIniCloud(path) && !fm.isFileDownloaded(path)) {
    await fm.downloadFileFromiCloud(path);
  }
  return true;
}

async function loadJSON(filenameOrPath) {
  const fm = getFileManager();
  const path = resolveAppPath(filenameOrPath);
  if (!(await ensureDownloaded(path))) {
    return null;
  }
  try {
    return JSON.parse(fm.readString(path));
  } catch {
    return null;
  }
}

async function saveJSON(filenameOrPath, value) {
  const fm = getFileManager();
  const path = resolveAppPath(filenameOrPath);
  const parent = path.substring(0, path.lastIndexOf("/"));
  if (parent && !fm.fileExists(parent)) {
    fm.createDirectory(parent, true);
  }
  fm.writeString(path, JSON.stringify(value, null, 2));
}

async function deleteFile(filenameOrPath) {
  const fm = getFileManager();
  const path = resolveAppPath(filenameOrPath);
  if (await ensureDownloaded(path)) {
    fm.remove(path);
  }
}

async function listConversationFiles() {
  const fm = getFileManager();
  const directory = getConversationsDirectory();
  if (fm.isFileStoredIniCloud(directory) && !fm.isFileDownloaded(directory)) {
    await fm.downloadFileFromiCloud(directory);
  }
  const names = fm.listContents(directory) || [];
  const paths = [];
  for (const name of names) {
    if (!name.endsWith(".json")) {
      continue;
    }
    const path = fm.joinPath(directory, name);
    await ensureDownloaded(path);
    paths.push(path);
  }
  return paths;
}

// ============================================================
// CONFIG
// ============================================================

async function loadConfig() {
  const stored = await loadJSON(CONFIG_FILE);
  if (!stored) {
    return null;
  }
  return deepMerge(DEFAULT_CONFIG, stored);
}

async function saveConfig(config) {
  await saveJSON(CONFIG_FILE, config);
}

// ============================================================
// KEYCHAIN
// ============================================================

function getRequiredKey(keychainKey, serviceName) {
  if (!Keychain.contains(keychainKey)) {
    throw new Error(
      `${serviceName} API key is missing.\n\nOpen Settings → API Keys to save it once.\nKeychain entry:\n${keychainKey}`
    );
  }
  const key = Keychain.get(keychainKey);
  if (!key || !key.trim()) {
    throw new Error(`${serviceName} API key is empty.`);
  }
  return key.trim();
}

function hasSecret(keychainKey) {
  if (!Keychain.contains(keychainKey)) {
    return false;
  }
  const key = Keychain.get(keychainKey);
  return !!(key && key.trim());
}

function getOptionalKey(keychainKey) {
  if (!hasSecret(keychainKey)) {
    return null;
  }
  return Keychain.get(keychainKey).trim();
}

function maskSecret(value) {
  const key = String(value || "").trim();
  if (!key) {
    return "(none)";
  }
  if (key.length <= 8) {
    return "••••";
  }
  return `••••${key.slice(-4)}`;
}

/**
 * Ensure a Keychain secret exists.
 * - If already saved: return it without prompting (unless forcePrompt).
 * - If missing: prompt once, save to Keychain, return it.
 */
async function ensureSecret(title, keychainKey, message, options = {}) {
  const forcePrompt = !!options.forcePrompt;
  const existing = getOptionalKey(keychainKey);

  if (existing && !forcePrompt) {
    return existing;
  }

  return await configureSecret(title, keychainKey, message, {
    allowKeepExisting: !!existing
  });
}

async function configureSecret(title, keychainKey, message, options = {}) {
  const existing = getOptionalKey(keychainKey) || "";
  const allowKeepExisting =
    options.allowKeepExisting !== undefined
      ? options.allowKeepExisting
      : !!existing;

  const alert = new Alert();
  alert.title = title;
  alert.message = existing
    ? `${message}\n\nSaved key: ${maskSecret(existing)}\nLeave the field blank and tap Keep Existing to reuse it.`
    : message;
  alert.addSecureTextField(
    existing ? "Paste new key to replace…" : "Paste API key here…",
    ""
  );
  alert.addAction(existing ? "Replace Key" : "Save Key");
  if (existing && allowKeepExisting) {
    alert.addAction("Keep Existing");
  }
  alert.addCancelAction("Cancel");

  const choice = await alert.presentAlert();
  if (choice === -1) {
    return null;
  }
  if (existing && allowKeepExisting && choice === 1) {
    return existing;
  }

  const newKey = alert.textFieldValue(0).trim();
  if (!newKey) {
    if (existing && allowKeepExisting) {
      return existing;
    }
    await showError(`${title} cannot be empty.`);
    return null;
  }
  Keychain.set(keychainKey, newKey);
  return newKey;
}

// ============================================================
// DEEPL
// ============================================================

async function translateWithDeepL(text, apiKey, languages) {
  const initialTarget = languages.defaultTarget;
  const firstResult = await requestDeepLTranslation(text, initialTarget, apiKey);
  const detectedLanguage = firstResult.translations[0].detected_source_language;

  let finalTranslation = firstResult.translations[0].text;
  let finalTarget = initialTarget;

  if (
    normalizeLanguage(detectedLanguage) === normalizeLanguage(initialTarget)
  ) {
    const alternateTarget = getAlternateTarget(languages);
    if (
      alternateTarget &&
      normalizeLanguage(alternateTarget) !== normalizeLanguage(detectedLanguage)
    ) {
      const secondResult = await requestDeepLTranslation(
        text,
        alternateTarget,
        apiKey
      );
      finalTranslation = secondResult.translations[0].text;
      finalTarget = alternateTarget;
    }
  }

  return {
    translation: finalTranslation,
    detectedLanguage,
    targetLanguage: finalTarget
  };
}

async function requestDeepLTranslation(text, targetLanguage, apiKey) {
  const key = String(apiKey || "").trim();
  if (!key) {
    throw new Error("DeepL API key is empty.");
  }

  const target = String(targetLanguage || "")
    .trim()
    .toUpperCase();
  if (!target) {
    throw new Error("DeepL target language is missing.");
  }

  // Prefer the host that matches the key type, but fall back if DeepL
  // says "Wrong endpoint" (common when Free vs paid host is mixed up).
  const primary = key.endsWith(":fx")
    ? "https://api-free.deepl.com/v2/translate"
    : "https://api.deepl.com/v2/translate";
  const fallback = key.endsWith(":fx")
    ? "https://api.deepl.com/v2/translate"
    : "https://api-free.deepl.com/v2/translate";

  try {
    return await postDeepLTranslate(primary, text, target, key);
  } catch (error) {
    const message = String(error?.message || error);
    if (/wrong endpoint|404|403|Forbidden|Not Found/i.test(message)) {
      return await postDeepLTranslate(fallback, text, target, key);
    }
    throw error;
  }
}

async function postDeepLTranslate(url, text, targetLanguage, apiKey) {
  const request = new Request(url);
  request.method = "POST";
  request.timeoutInterval = DEEPL_TIMEOUT;
  request.headers = {
    Authorization: `DeepL-Auth-Key ${apiKey}`,
    "Content-Type": "application/json",
    "User-Agent": "SmartTranslate/1.1 (Scriptable)"
  };
  request.body = JSON.stringify({
    text: [text],
    target_lang: targetLanguage
  });

  let response;
  try {
    response = await request.loadJSON();
  } catch (error) {
    const status = request.response?.statusCode;
    throw new Error(
      formatDeepLError(
        status,
        null,
        `Could not parse DeepL response.${error?.message ? ` ${error.message}` : ""}`
      )
    );
  }

  const status = request.response?.statusCode;
  if (status && status >= 400) {
    throw new Error(formatDeepLError(status, response));
  }

  if (!response?.translations?.[0]?.text) {
    throw new Error(formatDeepLError(status, response, "DeepL returned no translation."));
  }

  return response;
}

function formatDeepLError(statusCode, response, fallbackMessage) {
  const apiMessage =
    response?.message ||
    response?.error ||
    response?.detail ||
    (typeof response === "string" ? response : null);

  if (statusCode === 403) {
    return (
      "DeepL rejected the API key (403).\n\n" +
      "Check Account → API Keys & Limits:\n" +
      "https://www.deepl.com/your-account/keys\n\n" +
      "Use an API plan key (not a normal Translator login).\n" +
      (apiMessage ? `\nDeepL: ${apiMessage}` : "")
    );
  }
  if (statusCode === 456) {
    return (
      "DeepL quota exceeded (456).\n\n" +
      "Your character limit is used up for this billing period." +
      (apiMessage ? `\n\nDeepL: ${apiMessage}` : "")
    );
  }
  if (statusCode === 400) {
    return (
      "DeepL rejected the request (400).\n\n" +
      "Often a bad target language code." +
      (apiMessage ? `\n\nDeepL: ${apiMessage}` : "")
    );
  }
  if (statusCode === 404 || /wrong endpoint/i.test(String(apiMessage || ""))) {
    return (
      "DeepL wrong endpoint (404).\n\n" +
      "Free keys (:fx) use api-free.deepl.com.\n" +
      "Paid/Developer keys use api.deepl.com." +
      (apiMessage ? `\n\nDeepL: ${apiMessage}` : "")
    );
  }

  const parts = [];
  if (statusCode) {
    parts.push(`HTTP ${statusCode}`);
  }
  if (apiMessage) {
    parts.push(String(apiMessage));
  } else if (fallbackMessage) {
    parts.push(fallbackMessage);
  } else {
    parts.push("DeepL returned an invalid response.");
  }
  return parts.join(" — ");
}

function getAlternateTarget(languages) {
  const { primary, conversation, defaultTarget } = languages;
  if (normalizeLanguage(primary) !== normalizeLanguage(defaultTarget)) {
    return primary;
  }
  if (normalizeLanguage(conversation) !== normalizeLanguage(defaultTarget)) {
    return conversation;
  }
  return null;
}

// ============================================================
// TTS
// ============================================================

async function speakTranslation(text, targetLanguage, config) {
  if (
    config.speech.engine === "elevenlabs" &&
    config.speech.elevenlabs.enabled
  ) {
    const voice = config.speech.elevenlabs.voices[targetLanguage];
    if (voice?.voiceId) {
      try {
        const elevenLabsKey = getRequiredKey(
          ELEVENLABS_KEYCHAIN_KEY,
          "ElevenLabs"
        );
        await speakWithElevenLabs(text, voice.voiceId, elevenLabsKey, config);
        return;
      } catch (error) {
        console.error(
          `ElevenLabs failed: ${error.message}. Falling back to Apple speech.`
        );
      }
    }
  }
  await speakWithApple(text, targetLanguage, config);
}

async function speakWithApple(text, targetLanguage, config) {
  // Official API is Speech.speak(text) only. Rate/language options are not
  // documented; keep rate in config for future use / ElevenLabs parity.
  await Speech.speak(text);
}

async function speakWithElevenLabs(text, voiceId, apiKey, config) {
  const url = `https://api.elevenlabs.io/v1/text-to-speech/${encodeURIComponent(voiceId)}`;
  const request = new Request(url);
  request.method = "POST";
  request.timeoutInterval = ELEVENLABS_TIMEOUT;
  request.headers = {
    "xi-api-key": apiKey,
    "Content-Type": "application/json",
    Accept: "audio/mpeg"
  };
  request.body = JSON.stringify({
    text,
    model_id: config.speech.elevenlabs.modelId
  });

  const audioData = await request.load();
  if (!audioData || audioData.byteLength === 0) {
    throw new Error("Received empty audio data from ElevenLabs.");
  }

  const fm = FileManager.local();
  const audioPath = fm.joinPath(
    fm.temporaryDirectory(),
    `smart_translate_${Date.now()}.mp3`
  );
  fm.write(audioPath, audioData);

  // Prefer Sound.play when available; fall back to QuickLook (documented).
  if (typeof Sound !== "undefined" && typeof Sound.play === "function") {
    await Sound.play(audioPath);
  } else {
    await QuickLook.present(audioPath);
  }

  if (fm.fileExists(audioPath)) {
    fm.remove(audioPath);
  }
}

async function fetchElevenLabsVoices(apiKey) {
  const request = new Request("https://api.elevenlabs.io/v1/voices");
  request.method = "GET";
  request.timeoutInterval = ELEVENLABS_TIMEOUT;
  request.headers = { "xi-api-key": apiKey };
  const response = await request.loadJSON();
  if (!response?.voices) {
    throw new Error("ElevenLabs returned an invalid voice list.");
  }
  return response.voices;
}

// ============================================================
// ONE-SHOT TRANSLATE
// ============================================================

async function runOneShot(text, config) {
  const trimmed = (text || "").trim();
  if (!trimmed) {
    await showError("Please enter some text to translate.");
    return null;
  }
  if (trimmed.length > MAX_INPUT_LENGTH) {
    await showError(
      `Input is too long.\n\nMaximum: ${MAX_INPUT_LENGTH.toLocaleString()} characters.`
    );
    return null;
  }

  try {
    const deeplKey = getRequiredKey(DEEPL_KEYCHAIN_KEY, "DeepL");
    const result = await translateWithDeepL(
      trimmed,
      deeplKey,
      config.languages
    );
    Script.setShortcutOutput(result.translation);
    await speakTranslation(result.translation, result.targetLanguage, config);
    return result;
  } catch (error) {
    await showError(
      `Translation failed.\n\n${error?.message || "Unknown error."}`
    );
    return null;
  }
}

async function dictateText(config) {
  // Official Scriptable API is Dictation.start(locale), not Speech.dictate.
  // Locale should be a language id like "en" or "es" (not DeepL codes like EN-US).
  if (config.input.dictationLanguage === "auto") {
    return await Dictation.start();
  }
  const locale = normalizeLanguage(config.input.dictationLanguage).toLowerCase();
  return await Dictation.start(locale);
}

// ============================================================
// UI HELPERS
// ============================================================

async function showError(message) {
  const alert = new Alert();
  alert.title = "SmartTranslate Error";
  alert.message = message;
  alert.addAction("OK");
  await alert.presentAlert();
}

async function showSuccess(title, message) {
  const alert = new Alert();
  alert.title = title;
  alert.message = message;
  alert.addAction("OK");
  await alert.presentAlert();
}

/**
 * Sleek sectioned menu using UITable.
 *
 * sections: [
 *   {
 *     header?: string,
 *     rows: [{ id, title, subtitle?, symbol? }]
 *   }
 * ]
 *
 * Returns the selected row id, or null if dismissed.
 */
async function presentTableMenu({ title, subtitle, sections }) {
  let selectedId = null;
  const table = new UITable();
  table.showSeparators = true;

  if (title || subtitle) {
    const header = new UITableRow();
    header.isHeader = true;
    header.height = subtitle ? 52 : 40;
    const titleCell = UITableCell.text(title || "Menu", subtitle || "");
    titleCell.leftAligned();
    titleCell.widthWeight = 100;
    header.addCell(titleCell);
    table.addRow(header);
  }

  for (const section of sections || []) {
    if (section.header) {
      const sectionHeader = new UITableRow();
      sectionHeader.isHeader = true;
      sectionHeader.height = 32;
      const cell = UITableCell.text(section.header.toUpperCase());
      cell.leftAligned();
      cell.widthWeight = 100;
      sectionHeader.addCell(cell);
      table.addRow(sectionHeader);
    }

    for (const item of section.rows || []) {
      const row = new UITableRow();
      row.dismissOnSelect = true;
      row.height = item.subtitle ? 56 : 48;
      row.cellSpacing = 10;

      if (item.symbol && typeof SFSymbol !== "undefined") {
        try {
          const symbol = SFSymbol.named(item.symbol);
          if (symbol && symbol.image) {
            const imageCell = UITableCell.image(symbol.image);
            imageCell.widthWeight = 12;
            imageCell.centerAligned();
            row.addCell(imageCell);
          }
        } catch (error) {
          // Fall through without icon.
        }
      }

      const textCell = UITableCell.text(item.title, item.subtitle || "");
      textCell.leftAligned();
      textCell.widthWeight = item.symbol ? 78 : 90;
      row.addCell(textCell);

      if (item.disclosure) {
        const chevron = UITableCell.text("›");
        chevron.rightAligned();
        chevron.widthWeight = 10;
        row.addCell(chevron);
      }

      row.onSelect = () => {
        selectedId = item.id;
      };
      table.addRow(row);
    }
  }

  await table.present(false);
  return selectedId;
}

async function promptForText(title, message, defaultText = "") {
  const alert = new Alert();
  alert.title = title;
  alert.message = message;
  alert.addTextField("Enter text...", defaultText);
  alert.addAction("Continue");
  alert.addCancelAction("Cancel");
  const choice = await alert.presentAlert();
  return choice === -1 ? null : alert.textFieldValue(0).trim();
}

async function confirm(title, message) {
  const alert = new Alert();
  alert.title = title;
  alert.message = message;
  alert.addAction("Yes");
  alert.addAction("No");
  return (await alert.presentAlert()) === 0;
}

async function chooseFromList(title, items, message = null) {
  const alert = new Alert();
  alert.title = title;
  if (message) {
    alert.message = message;
  }
  for (const item of items) {
    alert.addAction(item);
  }
  alert.addCancelAction("Cancel");
  return await alert.presentSheet();
}

async function chooseBoolean(title, message, currentValue) {
  const alert = new Alert();
  alert.title = title;
  alert.message = message;
  alert.addAction(currentValue ? "Yes (Keep Enabled)" : "Yes (Enable)");
  alert.addAction(currentValue ? "No (Disable)" : "No (Keep Disabled)");
  alert.addCancelAction("Cancel");
  const choice = await alert.presentAlert();
  if (choice === -1) {
    return currentValue;
  }
  return choice === 0;
}

async function chooseSlider(title, currentValue, min, max) {
  const alert = new Alert();
  alert.title = title;
  alert.message = `Current value: ${currentValue.toFixed(2)}. Enter a new value between ${min} and ${max}.`;
  alert.addTextField("New value", String(currentValue));
  alert.addAction("Set");
  alert.addCancelAction("Cancel");
  const choice = await alert.presentAlert();
  if (choice === -1) {
    return currentValue;
  }

  const newValue = parseFloat(alert.textFieldValue(0));
  if (isNaN(newValue) || newValue < min || newValue > max) {
    await showError(
      `Invalid value. Please enter a number between ${min} and ${max}.`
    );
    return currentValue;
  }
  return newValue;
}

async function chooseLanguage(title, message, currentCode, excludedCodes = []) {
  const available = LANGUAGE_OPTIONS.filter(
    (lang) => !excludedCodes.includes(lang.code)
  );
  const labels = available.map((lang) => lang.name);
  const choice = await chooseFromList(title, labels, message);
  return choice === -1 ? null : available[choice].code;
}

// ============================================================
// UTILITIES
// ============================================================

function deepMerge(defaults, overrides) {
  const result = JSON.parse(JSON.stringify(defaults));
  for (const key in overrides) {
    if (!Object.prototype.hasOwnProperty.call(overrides, key)) {
      continue;
    }
    if (
      overrides[key] &&
      typeof overrides[key] === "object" &&
      !Array.isArray(overrides[key]) &&
      result[key] &&
      typeof result[key] === "object"
    ) {
      result[key] = deepMerge(result[key], overrides[key]);
    } else {
      result[key] = overrides[key];
    }
  }
  return result;
}

function normalizeLanguage(language) {
  return String(language || "")
    .toUpperCase()
    .split("-")[0];
}

function getLanguageDisplayName(code, includeCode = false) {
  const language = LANGUAGE_OPTIONS.find((item) => item.code === code);
  if (!language) {
    return code;
  }
  return includeCode ? `${language.name} (${language.code})` : language.name;
}

function unique(values) {
  return [...new Set(values.filter((v) => v))];
}

function generateUUID() {
  return "xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx".replace(/[xy]/g, function (c) {
    const r = (Math.random() * 16) | 0;
    const v = c === "x" ? r : (r & 0x3) | 0x8;
    return v.toString(16);
  });
}

function formatDate(value) {
  return new Date(value).toLocaleString();
}

function formatDuration(seconds) {
  const hours = Math.floor(seconds / 3600);
  const minutes = Math.floor((seconds % 3600) / 60);
  const remainingSeconds = seconds % 60;
  if (hours > 0) {
    return `${hours}h ${minutes}m`;
  }
  if (minutes > 0) {
    return `${minutes}m ${remainingSeconds}s`;
  }
  return `${remainingSeconds}s`;
}

const Shared = {
  APP_DIRECTORY,
  CONFIG_FILE,
  PEOPLE_FILE,
  ACTIVE_SESSION_FILE,
  CONVERSATIONS_DIRECTORY,
  DEEPL_KEYCHAIN_KEY,
  ELEVENLABS_KEYCHAIN_KEY,
  MAX_INPUT_LENGTH,
  MAX_VOICE_RESULTS,
  DEFAULT_CONFIG,
  LANGUAGE_OPTIONS,
  getFileManager,
  getAppDirectory,
  getConversationsDirectory,
  loadJSON,
  saveJSON,
  deleteFile,
  listConversationFiles,
  loadConfig,
  saveConfig,
  getRequiredKey,
  hasSecret,
  getOptionalKey,
  maskSecret,
  ensureSecret,
  configureSecret,
  translateWithDeepL,
  speakTranslation,
  fetchElevenLabsVoices,
  runOneShot,
  dictateText,
  showError,
  showSuccess,
  presentTableMenu,
  promptForText,
  confirm,
  chooseFromList,
  chooseBoolean,
  chooseSlider,
  chooseLanguage,
  deepMerge,
  normalizeLanguage,
  getLanguageDisplayName,
  unique,
  generateUUID,
  formatDate,
  formatDuration
};


// SmartTranslateConversation.js
//
// Conversation Mode engine for SmartTranslate v1.
//
// Locked V1 contract:
//   - Start / resume / end session
//   - Select or create person
//   - Optional metadata: title, context, notes (no auto location)
//   - Explicit speaker each turn: Me | Person
//   - Capture: Dictate (default), Type, or Paste
//   - Persist turn to active_session.json BEFORE TTS
//   - Continue / End after each turn
//   - History: list completed sessions → show transcript
//
// Out of scope: summaries, search, tags, diarization, SQLite,
// embeddings, cloud sync, audio archive, live custom UI.
//
// Version: 1.0.0

const Conversation = {
  runConversation,
  loadAllSessions,
  getConversationFilePath
};

// ============================================================
// ENTRY
// ============================================================

async function runConversation(config, hooks = {}) {
  const menu = await showConversationMenu(hooks);
  switch (menu) {
    case "continue": {
      const session = await loadActiveSession();
      if (!session) {
        await Shared.showError("No active conversation exists.");
        return;
      }
      await showSessionSummary(session);
      await turnLoop(session, config, hooks);
      break;
    }
    case "new":
      await runNewSessionFlow(config, hooks);
      break;
    case "history":
      await showHistory();
      break;
    default:
      break;
  }
}

async function showConversationMenu(hooks = {}) {
  const active = await loadActiveSession();

  if (active) {
    const choice = await Shared.presentTableMenu({
      title: "Conversation",
      subtitle: `Active with ${active.person.name} · ${active.session.turnCount} turns`,
      sections: [
        {
          rows: [
            {
              id: "continue",
              title: "Continue",
              subtitle: "Resume the active session",
              symbol: "play.fill"
            },
            {
              id: "history",
              title: "History",
              subtitle: "Browse saved conversations",
              symbol: "clock"
            },
            {
              id: "end",
              title: "End Active",
              subtitle: "Finalize and save",
              symbol: "checkmark.circle"
            },
            {
              id: "discard",
              title: "Discard & Start New",
              subtitle: "Delete active turns",
              symbol: "trash"
            }
          ]
        }
      ]
    });

    if (!choice) {
      return "cancel";
    }
    if (choice === "discard") {
      const abandon = await Shared.confirm(
        "Discard Active Conversation?",
        "This permanently discards the active conversation and its turns."
      );
      if (!abandon) {
        return "cancel";
      }
      await deleteActiveSession();
      return "new";
    }
    if (choice === "end") {
      await endConversation(active, hooks);
      return "cancel";
    }
    return choice;
  }

  const choice = await Shared.presentTableMenu({
    title: "Conversation",
    subtitle: "Start or review",
    sections: [
      {
        rows: [
          {
            id: "new",
            title: "New Conversation",
            subtitle: "Pick a person and begin",
            symbol: "plus.bubble"
          },
          {
            id: "history",
            title: "History",
            subtitle: "Browse saved conversations",
            symbol: "clock"
          }
        ]
      }
    ]
  });

  return choice || "cancel";
}

async function runNewSessionFlow(config, hooks = {}) {
  const session = await startConversation(config);
  if (!session) {
    return;
  }
  await showSessionSummary(session);
  await turnLoop(session, config, hooks);
}

// ============================================================
// START
// ============================================================

async function startConversation(config) {
  const person = await selectOrCreatePerson();
  if (!person) {
    return null;
  }

  const metadata = await collectConversationMetadata(person);
  if (!metadata) {
    return null;
  }

  const now = new Date().toISOString();
  const session = {
    schemaVersion: 1,
    session: {
      id: Shared.generateUUID(),
      status: "active",
      startedAt: now,
      endedAt: null,
      lastActivityAt: now,
      turnCount: 0,
      durationSeconds: null
    },
    person: {
      id: person.id,
      name: person.name
    },
    languages: {
      primary: config.languages.primary,
      conversation: config.languages.conversation,
      defaultTarget: config.languages.defaultTarget
    },
    metadata,
    turns: []
  };

  await saveActiveSession(session);
  return session;
}

async function collectConversationMetadata(person) {
  const defaultTitle = `${person.name} — ${new Date().toLocaleDateString()}`;

  const title = await Shared.promptForText(
    "Conversation Title",
    "Optional title for this conversation.",
    defaultTitle
  );
  if (title === null) {
    return null;
  }

  const context = await Shared.promptForText(
    "Context",
    "Optional context, such as Travel, Home, Work, or General."
  );
  if (context === null) {
    return null;
  }

  const notes = await Shared.promptForText(
    "Notes",
    "Optional notes about this conversation."
  );
  if (notes === null) {
    return null;
  }

  return {
    title: title.trim(),
    context: context.trim(),
    notes: notes.trim()
  };
}

// ============================================================
// TURN LOOP
// ============================================================

async function turnLoop(session, config, hooks = {}) {
  let current = session;

  while (true) {
    const outcome = await processTurn(current, config);
    if (outcome === "end") {
      await endConversation(current, hooks);
      return;
    }
    if (outcome === "cancel") {
      return;
    }
    // Reload from disk so we always hold the persisted session.
    current = (await loadActiveSession()) || current;

    const next = await promptAfterTurn(current);
    if (next === "end") {
      await endConversation(current, hooks);
      return;
    }
    if (next === "stop") {
      return;
    }
  }
}

async function processTurn(session, config) {
  const input = await getTurnInput(config);
  if (!input) {
    return "cancel";
  }

  const text = input.text.trim();
  if (!text) {
    await Shared.showError("No speech or text was captured.");
    return "continue";
  }

  if (text.length > Shared.MAX_INPUT_LENGTH) {
    await Shared.showError(
      `This turn is too long.\n\nMaximum: ${Shared.MAX_INPUT_LENGTH.toLocaleString()} characters.`
    );
    return "continue";
  }

  const speaker = await chooseSpeaker(session.person.name);
  if (!speaker) {
    return "cancel";
  }

  try {
    const deeplKey = Shared.getRequiredKey(
      Shared.DEEPL_KEYCHAIN_KEY,
      "DeepL"
    );
    const translation = await Shared.translateWithDeepL(
      text,
      deeplKey,
      session.languages
    );

    const turn = {
      id: Shared.generateUUID(),
      timestamp: new Date().toISOString(),
      speaker,
      sourceLanguage: translation.detectedLanguage,
      sourceText: text,
      targetLanguage: translation.targetLanguage,
      translatedText: translation.translation
    };

    // Persist BEFORE audio playback.
    session.turns.push(turn);
    session.session.turnCount = session.turns.length;
    session.session.lastActivityAt = new Date().toISOString();
    await saveActiveSession(session);

    Script.setShortcutOutput(
      JSON.stringify({
        action: "TURN_COMPLETE",
        sessionId: session.session.id,
        turn
      })
    );

    try {
      await Shared.speakTranslation(
        turn.translatedText,
        turn.targetLanguage,
        config
      );
    } catch (speechError) {
      console.error(`Speech failed: ${speechError.message}`);
      await Shared.showError(
        `Turn saved, but speech failed.\n\n${speechError?.message || "Unknown error."}`
      );
    }

    return "continue";
  } catch (error) {
    await Shared.showError(
      `Turn failed. The conversation was not modified.\n\n${error?.message || "Unknown error."}`
    );
    return "continue";
  }
}

async function getTurnInput(config) {
  const alert = new Alert();
  alert.title = "Conversation Turn";
  alert.message = "Capture the next turn.";
  alert.addAction("Dictate");
  alert.addAction("Type");
  alert.addAction("Paste");
  alert.addCancelAction("Cancel");

  const choice = await alert.presentAlert();
  if (choice === -1) {
    return null;
  }

  if (choice === 0) {
    try {
      const text = await Shared.dictateText(config);
      return { type: "dictation", text: text || "" };
    } catch (error) {
      await Shared.showError(
        `Dictation failed.\n\n${error?.message || "Unknown error."}`
      );
      return null;
    }
  }

  if (choice === 1) {
    const text = await Shared.promptForText(
      "Type Turn",
      "Enter what was said."
    );
    if (text === null) {
      return null;
    }
    return { type: "text", text };
  }

  if (choice === 2) {
    return {
      type: "clipboard",
      text: Pasteboard.paste() || ""
    };
  }

  return null;
}

async function chooseSpeaker(personName) {
  const alert = new Alert();
  alert.title = "Who Spoke?";
  alert.message = "Select the speaker for this turn.";
  alert.addAction("Me");
  alert.addAction(personName || "Person");
  alert.addCancelAction("Cancel");

  const choice = await alert.presentAlert();
  if (choice === -1) {
    return null;
  }
  return choice === 0 ? "me" : "person";
}

async function promptAfterTurn(session) {
  const alert = new Alert();
  alert.title = "Turn Saved";
  alert.message = `${session.person.name} · ${session.session.turnCount} turns\n\nContinue the conversation?`;
  alert.addAction("Continue");
  alert.addAction("End Conversation");
  alert.addAction("Pause (Keep Active)");

  const choice = await alert.presentAlert();
  if (choice === 0) {
    return "continue";
  }
  if (choice === 1) {
    return "end";
  }
  return "stop";
}

// ============================================================
// END
// ============================================================

async function endConversation(session, hooks = {}) {
  if (!session) {
    await Shared.showError("No active conversation exists.");
    return null;
  }

  const shouldEnd = await Shared.confirm(
    "End Conversation?",
    `Finish the conversation with ${session.person.name}?`
  );
  if (!shouldEnd) {
    return null;
  }

  const endedAt = new Date();
  session.session.status = "completed";
  session.session.endedAt = endedAt.toISOString();
  session.session.lastActivityAt = endedAt.toISOString();

  const start = new Date(session.session.startedAt);
  session.session.durationSeconds = Math.max(
    0,
    Math.round((endedAt.getTime() - start.getTime()) / 1000)
  );

  const finalPath = await saveCompletedConversation(session);
  await deleteActiveSession();

  await Shared.showSuccess(
    "Conversation Saved",
    `${session.person.name}\n\n${session.session.turnCount} turns\n${Shared.formatDuration(session.session.durationSeconds)}`
  );

  Script.setShortcutOutput(
    JSON.stringify({
      action: "COMPLETED",
      sessionId: session.session.id,
      filePath: finalPath
    })
  );

  if (typeof hooks.onCompleted === "function") {
    await hooks.onCompleted(session, finalPath);
  }

  return { session, finalPath };
}

// ============================================================
// PEOPLE
// ============================================================

async function selectOrCreatePerson() {
  const people = await loadPeople();
  const rows = people.map((person, index) => ({
    id: String(index),
    title: person.name,
    subtitle: "Existing person",
    symbol: "person.fill"
  }));
  rows.push({
    id: "new",
    title: "New Person",
    subtitle: "Create a profile",
    symbol: "person.badge.plus"
  });

  const choice = await Shared.presentTableMenu({
    title: "Who are you talking to?",
    subtitle: "Select or create",
    sections: [{ rows }]
  });

  if (!choice) {
    return null;
  }

  if (choice === "new") {
    const name = await Shared.promptForText(
      "New Person",
      "Enter the person's name."
    );
    if (!name) {
      return null;
    }
    const person = {
      id: Shared.generateUUID(),
      name: name.trim(),
      createdAt: new Date().toISOString()
    };
    people.push(person);
    await savePeople(people);
    return person;
  }

  return people[Number(choice)] || null;
}

async function loadPeople() {
  const data = await Shared.loadJSON(Shared.PEOPLE_FILE);
  return Array.isArray(data) ? data : [];
}

async function savePeople(people) {
  await Shared.saveJSON(Shared.PEOPLE_FILE, people);
}

// ============================================================
// HISTORY
// ============================================================

async function loadAllSessions() {
  const files = await Shared.listConversationFiles();
  const sessions = [];
  for (const path of files) {
    const session = await Shared.loadJSON(path);
    if (session && session.person && session.session) {
      session._filePath = path;
      sessions.push(session);
    }
  }
  sessions.sort(
    (a, b) =>
      new Date(b.session.startedAt).getTime() -
      new Date(a.session.startedAt).getTime()
  );
  return sessions;
}

function getConversationFilePath(session) {
  if (session._filePath) {
    return session._filePath;
  }
  const fm = Shared.getFileManager();
  return fm.joinPath(
    Shared.getConversationsDirectory(),
    `session_${session.session.id}.json`
  );
}

async function showHistory() {
  const sessions = await loadAllSessions();
  if (sessions.length === 0) {
    await Shared.showError("No saved conversations.");
    return;
  }

  const choice = await Shared.presentTableMenu({
    title: "History",
    subtitle: `${sessions.length} conversation${sessions.length === 1 ? "" : "s"}`,
    sections: [
      {
        rows: sessions.map((session, index) => ({
          id: String(index),
          title: session.person.name,
          subtitle: `${Shared.formatDate(session.session.startedAt)} · ${session.session.turnCount} turns`,
          symbol: "bubble.left.and.bubble.right",
          disclosure: true
        }))
      }
    ]
  });

  if (choice == null) {
    return;
  }
  await displayConversation(sessions[Number(choice)]);
}

async function displayConversation(session) {
  const lines = [];
  lines.push(session.person.name);
  lines.push("");
  lines.push(session.metadata?.title || "Untitled Conversation");
  if (session.metadata?.context) {
    lines.push(`Context: ${session.metadata.context}`);
  }
  lines.push(`Started: ${Shared.formatDate(session.session.startedAt)}`);
  lines.push(`Turns: ${session.session.turnCount}`);
  if (session.session.durationSeconds != null) {
    lines.push(
      `Duration: ${Shared.formatDuration(session.session.durationSeconds)}`
    );
  }
  lines.push("");

  for (const turn of session.turns || []) {
    const speaker =
      turn.speaker === "me" ? "ME" : session.person.name.toUpperCase();
    lines.push(`[${Shared.formatDate(turn.timestamp)}] ${speaker}`);
    lines.push(turn.sourceText);
    lines.push(`→ ${turn.translatedText}`);
    lines.push("");
  }

  const alert = new Alert();
  alert.title = session.person.name;
  alert.message = lines.join("\n");
  alert.addAction("Close");
  await alert.presentAlert();
}

async function showSessionSummary(session) {
  const alert = new Alert();
  alert.title = "Conversation Active";
  alert.message =
    `Person: ${session.person.name}\n\n` +
    `Languages: ${Shared.getLanguageDisplayName(session.languages.primary)} ↔ ${Shared.getLanguageDisplayName(session.languages.conversation)}\n\n` +
    `Turns: ${session.session.turnCount}`;
  alert.addAction("Continue");
  await alert.presentAlert();
}

// ============================================================
// SESSION STORAGE
// ============================================================

async function saveActiveSession(session) {
  await Shared.saveJSON(Shared.ACTIVE_SESSION_FILE, session);
}

async function loadActiveSession() {
  return await Shared.loadJSON(Shared.ACTIVE_SESSION_FILE);
}

async function deleteActiveSession() {
  await Shared.deleteFile(Shared.ACTIVE_SESSION_FILE);
}

async function saveCompletedConversation(session) {
  const fm = Shared.getFileManager();
  const filename = `session_${session.session.id}.json`;
  const path = fm.joinPath(Shared.getConversationsDirectory(), filename);
  await Shared.saveJSON(path, session);
  return path;
}


// SmartTranslate.js
//
// SmartTranslate v1 entry script for Scriptable.
//
// Menu:
//   Type         → type text, translate once, speak
//   Paste        → clipboard → translate once → speak
//   Dictate      → speech → translate once → speak
//   Conversation → multi-turn session (separate module)
//   Settings     → languages, API keys, speech engine
//
// Requires (same Scriptable folder):
//   SmartTranslateShared.js
//   SmartTranslateConversation.js
//
// Storage (iCloud documents):
//   SmartTranslate/config.json
//   SmartTranslate/people.json
//   SmartTranslate/active_session.json
//   SmartTranslate/conversations/session_<uuid>.json
//
// Keychain:
//   SMART_TRANSLATE_DEEPL_API_KEY
//   SMART_TRANSLATE_ELEVENLABS_API_KEY
//
// Version: 1.0.0
//
// IMPORTANT (Scriptable):
// Create THREE scripts with these EXACT names (no spaces, same capitalization):
//   SmartTranslateShared
//   SmartTranslateConversation
//   SmartTranslate
// Or paste the single-file bundle from scripts/dist/SmartTranslate.js instead.

async function main() {
  let config = await Shared.loadConfig();

  if (!config || !config.version) {
    const isFirstRun = !config;
    config = await runSetupWizard(isFirstRun, null);
    if (!config) {
      return;
    }
    await Shared.saveConfig(config);
    if (isFirstRun) {
      await Shared.showSuccess(
        "Setup Complete",
        "SmartTranslate is ready. Run the script again to translate."
      );
      return;
    }
  }

  const action = await showMainMenu(config);

  switch (action) {
    case "type":
      await runType(config);
      break;
    case "paste":
      await runPaste(config);
      break;
    case "dictate":
      await runDictate(config);
      break;
    case "conversation":
      await Conversation.runConversation(config);
      break;
    case "settings": {
      const newConfig = await runSetupWizard(false, config);
      if (newConfig) {
        await Shared.saveConfig(newConfig);
      }
      break;
    }
    default:
      break;
  }
}

// ============================================================
// MAIN MENU
// ============================================================

async function showMainMenu(config) {
  const alert = new Alert();
  alert.title = "SmartTranslate";
  const engine = config.speech.engine === "apple" ? "Apple" : "ElevenLabs";
  alert.message = `Speech: ${engine}\n${Shared.getLanguageDisplayName(config.languages.primary)} ↔ ${Shared.getLanguageDisplayName(config.languages.conversation)}`;
  alert.addAction("Type");
  alert.addAction("Paste");
  alert.addAction("Dictate");
  alert.addAction("Conversation");
  alert.addAction("Settings");
  alert.addCancelAction("Cancel");

  const choice = await alert.presentAlert();
  switch (choice) {
    case 0:
      return "type";
    case 1:
      return "paste";
    case 2:
      return "dictate";
    case 3:
      return "conversation";
    case 4:
      return "settings";
    default:
      return "cancel";
  }
}

// ============================================================
// ONE-SHOT WORKFLOWS
// ============================================================

async function runType(config) {
  const text = await Shared.promptForText(
    "Type",
    "Enter the text to translate."
  );
  if (text === null) {
    return;
  }
  await Shared.runOneShot(text, config);
}

async function runPaste(config) {
  const text = Pasteboard.paste() || "";
  if (!text.trim()) {
    await Shared.showError("Clipboard is empty.");
    return;
  }
  await Shared.runOneShot(text, config);
}

async function runDictate(config) {
  try {
    const text = await Shared.dictateText(config);
    if (!text || !text.trim()) {
      await Shared.showError("No speech was captured.");
      return;
    }
    await Shared.runOneShot(text, config);
  } catch (error) {
    await Shared.showError(
      `Dictation failed.\n\n${error?.message || "Unknown error."}`
    );
  }
}

// ============================================================
// SETUP / SETTINGS
// ============================================================

async function runSetupWizard(isFirstRun, existingConfig) {
  let config = Shared.deepMerge(Shared.DEFAULT_CONFIG, existingConfig || {});

  if (isFirstRun) {
    const welcome = new Alert();
    welcome.title = "Welcome to SmartTranslate";
    welcome.message =
      "This wizard configures languages and API keys. Data is stored in iCloud under Scriptable/SmartTranslate.";
    welcome.addAction("Start Setup");
    await welcome.present();
  }

  const deeplKey = await Shared.ensureSecret(
    "DeepL API Key",
    Shared.DEEPL_KEYCHAIN_KEY,
    "Paste your DeepL API key once. It stays in Scriptable Keychain and is reused automatically.\n\nhttps://www.deepl.com/your-account/keys"
  );
  if (!deeplKey) {
    return null;
  }

  config.languages.primary = await Shared.chooseLanguage(
    "Your Primary Language",
    "What is your primary language?",
    config.languages.primary
  );
  if (!config.languages.primary) {
    return null;
  }

  config.languages.conversation = await Shared.chooseLanguage(
    "Conversation Language",
    "What language are you translating with?",
    config.languages.conversation,
    [config.languages.primary]
  );
  if (!config.languages.conversation) {
    return null;
  }

  config.languages.defaultTarget = await Shared.chooseLanguage(
    "Default Translation Target",
    "When the input is not already this language, translate to:",
    config.languages.defaultTarget
  );
  if (!config.languages.defaultTarget) {
    return null;
  }

  const dictationOptions = [
    "Automatic",
    ...Shared.LANGUAGE_OPTIONS.map((lang) => `${lang.name} (${lang.code})`)
  ];
  const dictationChoice = await Shared.chooseFromList(
    "Dictation Language",
    dictationOptions,
    "Language hint for Dictate."
  );
  if (dictationChoice === -1) {
    return null;
  }
  config.input.dictationLanguage =
    dictationChoice === 0
      ? "auto"
      : Shared.LANGUAGE_OPTIONS[dictationChoice - 1].code;

  const engineChoice = await Shared.chooseFromList(
    "Speech Engine",
    ["Apple Native Voice", "ElevenLabs (requires API key)"],
    "Choose how translations are spoken."
  );
  if (engineChoice === -1) {
    return null;
  }
  config.speech.engine = engineChoice === 0 ? "apple" : "elevenlabs";

  if (config.speech.engine === "apple") {
    config.speech.apple.rate = await Shared.chooseSlider(
      "Apple Speech Rate",
      config.speech.apple.rate,
      0.1,
      1.0
    );
    config.speech.apple.pitch = await Shared.chooseSlider(
      "Apple Speech Pitch",
      config.speech.apple.pitch,
      0.5,
      2.0
    );
  } else {
    const elevenLabsKey = await Shared.configureSecret(
      "ElevenLabs API Key",
      Shared.ELEVENLABS_KEYCHAIN_KEY,
      "Enter your ElevenLabs API key."
    );
    config.speech.elevenlabs.enabled = !!elevenLabsKey;

    if (config.speech.elevenlabs.enabled) {
      const voiceResult = await configureElevenLabsVoices(
        config,
        elevenLabsKey
      );
      if (!voiceResult) {
        return null;
      }
      config.speech.elevenlabs.voices = voiceResult;
    }
  }

  const shouldTest = await Shared.chooseBoolean(
    "Test Configuration",
    "Test translation and speech now?",
    true
  );
  if (shouldTest) {
    await testConfiguration(config);
  }

  return config;
}

async function configureElevenLabsVoices(config, elevenLabsKey) {
  const languages = Shared.unique([
    config.languages.primary,
    config.languages.conversation,
    config.languages.defaultTarget
  ]);
  const newVoices = { ...config.speech.elevenlabs.voices };

  let allApiVoices;
  try {
    allApiVoices = await Shared.fetchElevenLabsVoices(elevenLabsKey);
  } catch (error) {
    await Shared.showError(
      `Could not load ElevenLabs voices.\n\n${error?.message || "Unknown error."}`
    );
    return null;
  }

  for (const langCode of languages) {
    const langName = Shared.getLanguageDisplayName(langCode);
    const compatibleVoices = allApiVoices
      .filter((v) => {
        const supported =
          v.labels?.language?.toLowerCase() ===
          langCode.slice(0, 2).toLowerCase();
        const isMultilingual =
          v.category === "premade" &&
          v.name.toLowerCase().includes("multilingual");
        return supported || isMultilingual;
      })
      .slice(0, Shared.MAX_VOICE_RESULTS);

    if (compatibleVoices.length === 0) {
      await Shared.showError(
        `No compatible ElevenLabs voices were found for ${langName}. Apple speech can still be used as fallback.`
      );
      continue;
    }

    const labels = compatibleVoices.map((v) => v.name);
    const choice = await Shared.chooseFromList(
      `${langName} AI Voice`,
      labels
    );
    if (choice === -1) {
      continue;
    }

    const selected = compatibleVoices[choice];
    newVoices[langCode] = {
      voiceId: selected.voice_id,
      name: selected.name
    };
  }

  return newVoices;
}

async function testConfiguration(config) {
  const testText = await Shared.promptForText(
    "Configuration Test",
    "Enter a short sentence to test translation and speech.",
    "Hello, world!"
  );
  if (!testText) {
    return;
  }

  try {
    const deeplKey = Shared.getRequiredKey(
      Shared.DEEPL_KEYCHAIN_KEY,
      "DeepL"
    );
    const { translation, detectedLanguage, targetLanguage } =
      await Shared.translateWithDeepL(testText, deeplKey, config.languages);

    const summary = `Detected: ${detectedLanguage}\nTarget: ${targetLanguage}\n\n${translation}`;
    const alert = new Alert();
    alert.title = "Translation Test";
    alert.message = summary;
    alert.addAction("OK");
    alert.addAction("Speak");
    const choice = await alert.presentAlert();
    if (choice === 1) {
      await Shared.speakTranslation(translation, targetLanguage, config);
    }
  } catch (error) {
    await Shared.showError(
      `Configuration test failed.\n\n${error?.message || "Unknown error."}`
    );
  }
}

await main();
Script.complete();
